// r29 -- wide_crossing  (the wire-aware cut)
//
//   (in_q) -[5 rounds]-> (mid_q) ==== 1024-bit crossing ====> [3 rounds] -> (out_q)
//
// ASYMMETRIC on purpose. With the crossing costing W, the two cycles are a
// and W + b, so the balance point is a = b + W rather than a = b. Moving two
// rounds ahead of the register shortens the crossing's cycle at the cost of
// lengthening the other, and the period drops by about W/2.
//
// GENERATED by commands/generate_wide_crossing_benchmark.py -- edit that, not this file. The mid-register
// reset value below is computed there, because moving the register past a round
// changes the value it must reset to.

module r29_wide_crossing (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [63:0]  din,
    output logic [63:0]  dout
);
  // PORTS ARE NARROW ON PURPOSE. Exposing the whole 1024-bit crossing at the top level
  // asked Innovus to spread 2049 pins around a die with 1756 free tracks, which fails
  // outright (IMPPTN-970) -- and it was never realistic: real designs carry wide buses
  // internally and present narrow interfaces. The crossing is still 1024 bits wide
  // where it matters, between the two clusters.
  localparam int W = 1024;
  localparam logic [W-1:0] MID_RESET = 1024'h3333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333333;

  function automatic logic [W-1:0] rotl1 (input logic [W-1:0] x);
    rotl1 = (x << 1) | (x >> (W - 1));
  endfunction
  function automatic logic [W-1:0] rotl3 (input logic [W-1:0] x);
    rotl3 = (x << 3) | (x >> (W - 3));
  endfunction
  function automatic logic [W-1:0] rotl5 (input logic [W-1:0] x);
    rotl5 = (x << 5) | (x >> (W - 5));
  endfunction
  function automatic logic [W-1:0] rotl7 (input logic [W-1:0] x);
    rotl7 = (x << 7) | (x >> (W - 7));
  endfunction
  function automatic logic [W-1:0] rotl11 (input logic [W-1:0] x);
    rotl11 = (x << 11) | (x >> (W - 11));
  endfunction
  function automatic logic [W-1:0] rotl13 (input logic [W-1:0] x);
    rotl13 = (x << 13) | (x >> (W - 13));
  endfunction
  function automatic logic [W-1:0] rotl17 (input logic [W-1:0] x);
    rotl17 = (x << 17) | (x >> (W - 17));
  endfunction
  function automatic logic [W-1:0] rotl19 (input logic [W-1:0] x);
    rotl19 = (x << 19) | (x >> (W - 19));
  endfunction
  function automatic logic [W-1:0] rotl23 (input logic [W-1:0] x);
    rotl23 = (x << 23) | (x >> (W - 23));
  endfunction

  // round 0: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_0 (input logic [W-1:0] x);
    rnd_0 = (x ^ 1024'hA5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5) ^ (rotl1(x) & rotl3(x));
  endfunction
  // round 1: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_1 (input logic [W-1:0] x);
    rnd_1 = (x ^ 1024'h3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C) ^ (rotl1(x) & rotl5(x));
  endfunction
  // round 2: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_2 (input logic [W-1:0] x);
    rnd_2 = (x ^ 1024'h5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A5A) ^ (rotl1(x) & rotl7(x));
  endfunction
  // round 3: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_3 (input logic [W-1:0] x);
    rnd_3 = (x ^ 1024'hC3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3C3) ^ (rotl1(x) & rotl11(x));
  endfunction
  // round 4: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_4 (input logic [W-1:0] x);
    rnd_4 = (x ^ 1024'h6969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969) ^ (rotl1(x) & rotl13(x));
  endfunction
  // round 5: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_5 (input logic [W-1:0] x);
    rnd_5 = (x ^ 1024'h9696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696969696) ^ (rotl1(x) & rotl17(x));
  endfunction
  // round 6: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_6 (input logic [W-1:0] x);
    rnd_6 = (x ^ 1024'hF0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0) ^ (rotl1(x) & rotl19(x));
  endfunction
  // round 7: nonlinear (AND of two rotations), 2 gate levels/bit
  function automatic logic [W-1:0] rnd_7 (input logic [W-1:0] x);
    rnd_7 = (x ^ 1024'h0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F0F) ^ (rotl1(x) & rotl23(x));
  endfunction

  logic [W-1:0] in_q, mid_q, out_q, bus, a_out, b_out;

  // Expand 64 -> W with a distinct constant per 64-bit slice, so the slices are not
  // copies of each other and synthesis cannot share the logic between them.
  logic [W-1:0] wide_in;
  always_comb
    for (int s = 0; s < W/64; s++)
      wide_in[s*64 +: 64] = din ^ (64'h9E3779B97F4A7C15 * unsigned'(s + 1));

  always_ff @(posedge clk) begin
    if (!rst_n) in_q <= '0;
    else        in_q <= wide_in;
  end

  // ---- cluster A: 5 of 8 rounds -------------------------------------
  always_comb a_out = rnd_4(rnd_3(rnd_2(rnd_1(rnd_0(in_q)))));

  always_ff @(posedge clk) begin
    if (!rst_n) mid_q <= MID_RESET;
    else        mid_q <= a_out;
  end

  // THE CROSSING. Pure wire: 1024 bits from cluster A to cluster B.
  always_comb bus = mid_q;

  // ---- cluster B: the remaining 3 rounds ---------------------------
  always_comb b_out = rnd_7(rnd_6(rnd_5(bus)));

  always_ff @(posedge clk) begin
    if (!rst_n) out_q <= '0;
    else        out_q <= b_out;
  end

  // Reduce W -> 64 by XOR-folding, which keeps every internal bit observable at the
  // output (needed for the equivalence check to have any power) without adding ports.
  always_comb begin
    dout = 64'h0;
    for (int s = 0; s < W/64; s++)
      dout = dout ^ out_q[s*64 +: 64];
  end

endmodule
